const d = $input.first().json;
const csat = Number(d['CSAT']);
const nps = Number(d['NPS']);
const renewal = Number(d['Days to renewal']);
const contact = Number(d['Days since last contact']);

let risk = 0;
const reasons = [];
if (csat < 7) { risk += 2; reasons.push('Low CSAT'); }
else if (csat < 9) { risk += 1; reasons.push('CSAT slipping'); }
if (nps < 6) { risk += 2; reasons.push('Low NPS'); }
else if (nps < 8) { risk += 1; reasons.push('NPS passive'); }
if (contact > 30) { risk += 2; reasons.push('No contact in over 30 days'); }
else if (contact > 21) { risk += 1; reasons.push('Contact overdue'); }
if (renewal < 60 && risk > 0) { risk += 1; reasons.push('Renewal inside 60 days'); }

const status = risk >= 4 ? 'Red' : risk >= 2 ? 'Yellow' : 'Green';
const action = status === 'Red' ? 'Call the daily user lead today and update the sponsor'
  : status === 'Yellow' ? 'Schedule a check in this week'
  : 'Keep the normal cadence and look for expansion';

return [{ json: { account: d['Account name'], status, reasons: reasons.join(', ') || 'No flags', action } }];
